<?php
declare(strict_types=1);
foreach(['DB_HOST','DB_PORT','DB_NAME','DB_USER','DB_PASS'] as $k)if(($v=getenv($k))!==false)$_ENV[$k]=$v;
use App\Core\Database;use App\Core\Request;use App\Services\PaymentService;
require dirname(__DIR__,2).'/vendor/autoload.php';
if(getenv('MIRANDA_FINANCE_TEST')!=='1'||!preg_match('/^miranda_finance_data_test_/',(string)getenv('DB_NAME')))exit(2);
function cc(bool $v,string $m):void{if(!$v)throw new RuntimeException($m);}
if(($argv[1]??'')==='worker'){
  [$school,$student,$fee,$item,$user,$method,$key,$barrier]=array_map('strval',array_slice($argv,2));
  while(!is_file($barrier))usleep(1000);
  Request::set('auth_user',['id'=>(int)$user,'role'=>'admin','school_id'=>(int)$school]);
  $r=(new PaymentService())->create(['student_id'=>(int)$student,'amount_paid'=>150,'payment_date'=>'2027-01-10','payment_method_id'=>(int)$method,'idempotency_key'=>$key,'allocations'=>[['monthly_fee_id'=>(int)$fee,'amount'=>100],['student_financial_item_id'=>(int)$item,'amount'=>50]]]);
  echo json_encode($r);exit;
}
$p=Database::connect();$x=(string)getmypid();$p->prepare('INSERT INTO schools(name,code,slug,email_domain)VALUES(?,?,?,?)')->execute(['Concurrent '.$x,'CC'.$x,'cc-'.$x,'cc-'.$x.'.test']);$school=(int)$p->lastInsertId();$p->prepare('INSERT INTO users(school_id,first_name,last_name,email,password,role,status)VALUES(?,?,?,?,?,"admin","ACTIVE")')->execute([$school,'Concurrent','Tester','cc-'.$x.'@t','x']);$user=(int)$p->lastInsertId();$p->prepare('INSERT INTO students(school_id,first_name,last_name,class_level,monthly_amount,status)VALUES(?,?,?,?,?,"REGISTERED")')->execute([$school,'Concurrent','Student','1AC',100]);$student=(int)$p->lastInsertId();$method=(int)$p->query('SELECT id FROM payment_methods WHERE status="ACTIVE" LIMIT 1')->fetchColumn();$p->prepare('INSERT INTO monthly_fees(school_id,student_id,month_label,year_value,total_amount,amount_paid,remaining_amount,status)VALUES(?,?,"01",2027,100,0,100,"UNPAID")')->execute([$school,$student]);$fee=(int)$p->lastInsertId();$p->prepare('INSERT INTO student_financial_items(school_id,student_id,item_code,label,unit_amount,total_amount,paid_amount,status)VALUES(?,?,?,?,?,?,0,"UNPAID")')->execute([$school,$student,'T-'.$x,'Transport',50,50]);$item=(int)$p->lastInsertId();$p->prepare('INSERT INTO student_financial_item_details(student_financial_item_id,school_id,original_amount,final_amount)VALUES(?,?,50,50)')->execute([$item,$school]);
function race(array $args,string $tag):array{ $barrier=sys_get_temp_dir().'/miranda-race-'.$tag.'-'.getmypid();@unlink($barrier);$cmd=escapeshellarg(PHP_BINARY).' '.escapeshellarg(__FILE__).' worker '.implode(' ',array_map('escapeshellarg',[...$args,$barrier]));$spawn=static function($cmd){$pipes=[];$p=proc_open($cmd,[1=>['pipe','w'],2=>['pipe','w']],$pipes);return [$p,$pipes,microtime(true)];};[$a,$pa,$ta]=$spawn($cmd);[$b,$pb,$tb]=$spawn($cmd);usleep(100000);touch($barrier);$outA=stream_get_contents($pa[1]);$errA=stream_get_contents($pa[2]);$outB=stream_get_contents($pb[1]);$errB=stream_get_contents($pb[2]);$exitA=proc_close($a);$exitB=proc_close($b);@unlink($barrier);return [['pid'=>'A','exit'=>$exitA,'stdout'=>$outA,'stderr'=>$errA,'response'=>json_decode($outA,true),'elapsed_ms'=>round((microtime(true)-$ta)*1000)],['pid'=>'B','exit'=>$exitB,'stdout'=>$outB,'stderr'=>$errB,'response'=>json_decode($outB,true),'elapsed_ms'=>round((microtime(true)-$tb)*1000)]];}
$same=race([$school,$student,$fee,$item,$user,$method,'same-'.$x],'same');cc(count(array_filter($same,fn($r)=>isset($r['response']['id'])))===2,'same-key responses invalid: '.json_encode($same));$q=$p->prepare('SELECT COUNT(*) FROM payments WHERE school_id=?');$q->execute([$school]);cc((int)$q->fetchColumn()===1,'same key created duplicate payment');$q=$p->prepare('SELECT COUNT(*) FROM payment_allocations WHERE school_id=?');$q->execute([$school]);cc((int)$q->fetchColumn()===2,'same key created duplicate allocations');
$different=race([$school,$student,$fee,$item,$user,$method,'different-'.$x],'different');cc(count(array_filter($different,fn($r)=>isset($r['response']['id'])))===0,'different keys unexpectedly created a second payment: '.json_encode($different));$q=$p->prepare('SELECT amount_paid,remaining_amount FROM monthly_fees WHERE id=?');$q->execute([$fee]);$m=$q->fetch();cc((float)$m['amount_paid']<=100&&(float)$m['remaining_amount']>=0,'monthly balance exceeded');$q=$p->prepare('SELECT paid_amount FROM student_financial_items WHERE id=?');$q->execute([$item]);cc((float)$q->fetchColumn()<=50,'transport balance exceeded');echo "unified payment concurrency integration: OK\n";
